SELECT id, device, ROW_NUMBER() OVER (ORDER BY started_at, id) AS row_seq, ROW_NUMBER() OVER (PARTITION BY country ORDER BY started_at, id) AS seq_no, ROW_NUMBER() OVER (PARTITION BY country ORDER BY started_at, id) AS seq_no_2, FIRST_VALUE(browser) IGNORE NULLS OVER (PARTITION BY device, country ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_browser FROM sessions
